def has_cycle_of_length(graph, length):
    """Check if graph has a cycle of given length"""
    # BFS-based cycle detection
    for start in range(n):
        # BFS to find cycles
        visited = {start: [start]}
        queue = [start]
        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if neighbor == start and len(visited[node]) == length:
                    return True
                if neighbor not in visited and len(visited[node]) < length:
                    visited[neighbor] = visited[node] + [neighbor]
                    queue.append(neighbor)
    return False

def has_short_cycle(graph, max_len=6):
    """Check if graph has any cycle of length 3 to max_len"""
    for length in range(3, max_len + 1):
        if has_cycle_of_length(graph, length):
            return True
    return False

def is_k_colorable(graph, k):
    """Check if graph is k-colorable using backtracking"""
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in graph[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

